class MyCompressor(BaseDocumentCompressor):
    def compress_documents(self, docs, query):
        return [doc for doc in docs if query in doc.page_content]

def rrf_score(rank_lists: list[list[str]], k: int = 60) -> dict:
    """Reciprocal Rank Fusion: 多路检索结果按排名融合。
    score = Σ 1/(k+rank), 在多个列表里都靠前的文档得分最高"""
    scores = {}
    for docs in rank_lists:
        for rank, doc_id in enumerate(docs, 1):
            scores[doc_id] = scores.get(doc_id, 0) + 1 / (k + rank)
    return dict(sorted(scores.items(), key=lambda x: -x[1]))

